private LocalDate issuedAt;
private BigDecimal taxRate;
private String currency;

public LocalDate getIssuedAt() {
    return issuedAt;
}

public void setIssuedAt(LocalDate issuedAt) {
    this.issuedAt = issuedAt;
}

public BigDecimal getTaxRate() {
    return taxRate;
}

public void setTaxRate(BigDecimal taxRate) {
    this.taxRate = taxRate;
}

public String getCurrency() {
    return currency;
}

public void setCurrency(String currency) {
    this.currency = currency;
}

private LocalDate dueDate;

public LocalDate getDueDate() {
    return dueDate;
}

public void setDueDate(LocalDate dueDate) {
    this.dueDate = dueDate;
}

public void setAmount(long amount) {
    if (amount < 0) {
        throw new IllegalArgumentException("amount must not be negative");
    }
    this.amount = amount;
}

public record Invoice(String number, long amount, LocalDate issuedAt,
        BigDecimal taxRate, String currency, LocalDate dueDate) {
    public Invoice {
        if (amount < 0) {
            throw new IllegalArgumentException("amount must not be negative");
        }
    }

    public Invoice withAmount(long value) {
        return new Invoice(number, value, issuedAt, taxRate, currency, dueDate);
    }
}
